import React from "react";

function UserList({ users }) {
  const getRoleColor = (role) => {
    switch (role) {
      case "admin": return "text-red-600 font-semibold";
      case "editor": return "text-blue-600";
      case "viewer": return "text-gray-600";
      default: return "text-gray-500";
    }
  };

  const getRoleIcon = (role) => {
    switch (role) {
      case "admin": return "👑";
      case "editor": return "✏️";
      case "viewer": return "👁️";
      default: return "👤";
    }
  };

  const getRoleGradient = (role) => {
    switch (role) {
      case "admin": return "from-red-500 to-pink-500";
      case "editor": return "from-blue-500 to-cyan-500";
      case "viewer": return "from-gray-500 to-slate-500";
      default: return "from-gray-400 to-gray-500";
    }
  };

  return (
    <div className="w-72 bg-gradient-to-b from-gray-50 to-blue-50 border-l border-gray-200 p-6 shadow-lg">
      <div className="mb-6">
        <h2 className="text-xl font-bold text-gray-800 mb-2 flex items-center">
          <span className="mr-2">👥</span>
          Connected Users
        </h2>
        <div className="bg-gradient-to-r from-blue-500 to-purple-500 text-white px-3 py-1 rounded-full text-sm font-medium inline-block">
          {users.length} {users.length === 1 ? 'user' : 'users'}
        </div>
      </div>

      {users.length === 0 ? (
        <div className="text-center py-12">
          <div className="w-20 h-20 bg-gradient-to-br from-gray-200 to-gray-300 rounded-full flex items-center justify-center mx-auto mb-4">
            <span className="text-4xl">👤</span>
          </div>
          <p className="text-gray-500 font-medium">No users connected</p>
          <p className="text-gray-400 text-sm">Be the first to join!</p>
        </div>
      ) : (
        <div className="space-y-3">
          {users.map((user) => (
            <div key={user.id} className="group">
              <div className="bg-white/80 backdrop-blur-sm rounded-xl p-4 shadow-lg border border-white/50 hover:shadow-xl transition-all duration-200 hover:scale-105">
                <div className="flex items-center space-x-3">
                  <div className={`w-12 h-12 bg-gradient-to-br ${getRoleGradient(user.role)} rounded-full flex items-center justify-center shadow-lg`}>
                    <span className="text-2xl">{getRoleIcon(user.role)}</span>
                  </div>
                  <div className="flex-1">
                    <div className="font-semibold text-gray-900 group-hover:text-gray-700 transition-colors">
                      {user.username}
                    </div>
                    <div className={`text-sm ${getRoleColor(user.role)} flex items-center space-x-1`}>
                      <span>{getRoleIcon(user.role)}</span>
                      <span className="capitalize">{user.role}</span>
                    </div>
                  </div>
                  <div className="flex flex-col items-end space-y-1">
                    <div className="w-3 h-3 bg-green-400 rounded-full animate-pulse shadow-lg"></div>
                    <div className="text-xs text-green-600 font-medium">Online</div>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Role Legend */}
      <div className="mt-8 p-4 bg-white/60 backdrop-blur-sm rounded-xl border border-white/50 shadow-lg">
        <h3 className="font-semibold text-gray-800 mb-3 text-center">Role Permissions</h3>
        <div className="space-y-2 text-sm">
          <div className="flex items-center space-x-2 p-2 bg-gradient-to-r from-red-50 to-pink-50 rounded-lg border border-red-100">
            <span className="text-lg">👑</span>
            <div>
              <div className="font-medium text-red-800">Admin</div>
              <div className="text-red-600 text-xs">Full control + clear board</div>
            </div>
          </div>
          <div className="flex items-center space-x-2 p-2 bg-gradient-to-r from-blue-50 to-cyan-50 rounded-lg border border-blue-100">
            <span className="text-lg">✏️</span>
            <div>
              <div className="font-medium text-blue-800">Editor</div>
              <div className="text-blue-600 text-xs">Can draw and erase</div>
            </div>
          </div>
          <div className="flex items-center space-x-2 p-2 bg-gradient-to-r from-gray-50 to-slate-50 rounded-lg border border-gray-100">
            <span className="text-lg">👁️</span>
            <div>
              <div className="font-medium text-gray-800">Viewer</div>
              <div className="text-gray-600 text-xs">Read-only access</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default UserList;
